using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class ApiTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    public ApiTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool, Description("Fetches data from an external API endpoint.")]
    public async Task<string> FetchData(
        [Description("The relative path to query (e.g. \"users/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt to summarize the provided text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Desired summary style (brief, detailed, bullet-points).")] string style = "brief")
    {
        yield return new ChatMessage(
            ChatRole.User,
            $"Summarize the following text in a {style} style:\n\n{text}");
    }
}

